using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;
namespace CityForge.Editor{
[InitializeOnLoad] public static class ForestTreesTrial{
const string Root="Assets/CityForge/Art/Environment/ForestTreesTrial/";
const string Work="/Users/joelinstrum/Documents/Codex/2026-10-08/tre/work/";
static ForestTreesTrial(){EditorApplication.update+=Tick;}
static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isPlaying)return;if(File.Exists(Work+"try-trees")){File.Delete(Work+"try-trees");Run();}if(File.Exists(Work+"inspect-trees")){File.Delete(Work+"inspect-trees");Inspect();}}
static Material GetMaterial(string key,Color color){string path=Root+key+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(mat,path);}mat.SetColor("_BaseColor",color);mat.SetFloat("_Smoothness",.12f);mat.SetFloat("_Cull",0);mat.enableInstancing=true;EditorUtility.SetDirty(mat);return mat;}
static GameObject[] MakePrefabs(string key){var model=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"FBX/"+key+".fbx");var trunk=GetMaterial("Bark",new Color(.191f,.121f,.075f));var leaf=GetMaterial("Leaves",new Color(.30f,.48f,.16f));return model.GetComponentsInChildren<MeshFilter>().OrderBy(m=>m.transform.localPosition.x).Select((mf,i)=>{var go=new GameObject(key+" tree "+(i+1));var child=new GameObject("Tree mesh");child.transform.SetParent(go.transform,false);child.transform.localScale=Vector3.one*100;var bounds=mf.sharedMesh.bounds;child.transform.localPosition=new Vector3(-bounds.center.x*100,-bounds.min.y*100,-bounds.center.z*100);child.AddComponent<MeshFilter>().sharedMesh=mf.sharedMesh;var renderer=child.AddComponent<MeshRenderer>();renderer.sharedMaterials=mf.GetComponent<MeshRenderer>().sharedMaterials.Select(m=>m.name.ToLower().Contains("tronco")?trunk:leaf).ToArray();var result=PrefabUtility.SaveAsPrefabAsset(go,Root+key.Replace(" ","_")+"_"+(i+1)+".prefab");UnityEngine.Object.DestroyImmediate(go);return result;}).ToArray();}
[MenuItem("CityForge/Ground Study/Try Forest Trees Zoom 1")]
public static void Run(){var low=MakePrefabs("low poly");var medium=MakePrefabs("medium poly");AssetDatabase.SaveAssets();var scene=EditorSceneManager.OpenScene("Assets/CityForge/Art/Environment/MapMagicMeadowStudy/MeadowZoom1.unity",OpenSceneMode.Single);var root=scene.GetRootGameObjects().First(g=>g.name=="Authored woodland edge");var originals=root.transform.Cast<Transform>().ToArray();int count=0;foreach(var old in originals){var renderers=old.GetComponentsInChildren<Renderer>();if(renderers.Length==0)continue;var bounds=renderers[0].bounds;foreach(var renderer in renderers)bounds.Encapsulate(renderer.bounds);float height=bounds.size.y;var prefab=low[count%low.Length];var replacement=(GameObject)PrefabUtility.InstantiatePrefab(prefab,scene);replacement.transform.SetParent(root.transform);replacement.transform.position=old.position;replacement.transform.rotation=old.rotation;float nativeHeight=prefab.GetComponentInChildren<MeshFilter>().sharedMesh.bounds.size.y*100;replacement.transform.localScale=Vector3.one*Mathf.Clamp(height/nativeHeight,.08f,1.5f);UnityEngine.Object.DestroyImmediate(old.gameObject);count++;}root.name="Forest pack woodland — low detail";EditorSceneManager.SaveScene(scene,Root+"ForestTreesZoom1.unity");var camera=UnityEngine.Object.FindFirstObjectByType<Camera>();Capture(camera,"ForestTrees_Low_Zoom1");Debug.Log("FOREST TREES TRIAL: "+count+" replacements");
foreach(var old in root.transform.Cast<Transform>().ToArray()){int index=Array.FindIndex(low,p=>old.name==p.name);if(index<0)continue;var bounds=old.GetComponentInChildren<Renderer>().bounds;var replacement=(GameObject)PrefabUtility.InstantiatePrefab(medium[index],scene);replacement.transform.SetParent(root.transform);replacement.transform.position=old.position;replacement.transform.rotation=old.rotation;float nativeHeight=medium[index].GetComponentInChildren<MeshFilter>().sharedMesh.bounds.size.y*100;replacement.transform.localScale=Vector3.one*(bounds.size.y/nativeHeight);UnityEngine.Object.DestroyImmediate(old.gameObject);}root.name="Forest pack woodland — medium detail";EditorSceneManager.SaveScene(scene,Root+"ForestTreesMediumZoom1.unity");Capture(camera,"ForestTrees_Medium_Zoom1");
// An isolated comparison preserves the same shape ordering by source X position.
var gallery=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);UnityEngine.SceneManagement.SceneManager.SetActiveScene(gallery);foreach(var obj in scene.GetRootGameObjects())obj.SetActive(false);var ground=GameObject.CreatePrimitive(PrimitiveType.Plane);ground.transform.localScale=new Vector3(22,1,7);ground.GetComponent<Renderer>().sharedMaterial=GetMaterial("GalleryGround",new Color(.37f,.42f,.31f));var sun=new GameObject("Sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.6f;sun.shadows=LightShadows.Soft;sun.transform.rotation=Quaternion.Euler(45,210,0);RenderSettings.ambientLight=new Color(.5f,.5f,.5f);var cam=new GameObject("Comparison camera").AddComponent<Camera>();cam.orthographic=true;cam.orthographicSize=65;cam.transform.rotation=Quaternion.Euler(35,0,0);cam.transform.position=new Vector3(0,8,0)-cam.transform.forward*160;cam.backgroundColor=new Color(.8f,.83f,.79f);cam.clearFlags=CameraClearFlags.SolidColor;cam.GetUniversalAdditionalCameraData().renderPostProcessing=true;
foreach(var pair in new[]{low,medium}){for(int i=0;i<pair.Length;i++){var obj=(GameObject)PrefabUtility.InstantiatePrefab(pair[i],gallery);obj.transform.position=new Vector3((i-4.5f)*19,0,pair==low?-16:16);obj.transform.localScale=Vector3.one*.8f;}}EditorSceneManager.SaveScene(gallery,Root+"TreeDetailComparison.unity");Capture(cam,"ForestTrees_DetailComparison");EditorSceneManager.CloseScene(gallery,true);foreach(var obj in scene.GetRootGameObjects())obj.SetActive(true);UnityEngine.SceneManagement.SceneManager.SetActiveScene(scene);EditorSceneManager.SaveScene(scene,Root+"ForestTreesMediumZoom1.unity");}
static void Capture(Camera cam,string name){var rt=new RenderTexture(3840,2160,24);rt.Create();var previous=RenderTexture.active;try{RenderPipeline.SubmitRenderRequest(cam,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var im=new Texture2D(3840,2160,TextureFormat.RGB24,false);im.ReadPixels(new Rect(0,0,3840,2160),0,0);im.Apply();File.WriteAllBytes("/Users/joelinstrum/Documents/Codex/2026-10-08/tre/outputs/"+name+".png",im.EncodeToPNG());UnityEngine.Object.DestroyImmediate(im);}finally{RenderTexture.active=previous;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
static void Inspect(){var lines=new System.Collections.Generic.List<string>();foreach(var key in new[]{"low poly","medium poly"}){var path=Root+"FBX/"+key+".fbx";var importer=(ModelImporter)AssetImporter.GetAtPath(path);importer.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;importer.SaveAndReimport();var model=AssetDatabase.LoadAssetAtPath<GameObject>(path);lines.Add(key);foreach(var tr in model.GetComponentsInChildren<Transform>(true)){var mf=tr.GetComponent<MeshFilter>();lines.Add(tr.name+" pos="+tr.localPosition+" scale="+tr.localScale+(mf?" verts="+mf.sharedMesh.vertexCount+" tris="+mf.sharedMesh.triangles.Length/3+" bounds="+mf.sharedMesh.bounds:""));}foreach(var mat in AssetDatabase.LoadAllAssetsAtPath(path).OfType<Material>())lines.Add("MAT "+mat.name+" "+mat.color+" texture="+mat.mainTexture); }File.WriteAllLines(Work+"tree-inventory.txt",lines);}
}}
